import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {BOARD_PROFILES} from '../src/boards.js';
const sha=b=>createHash('sha256').update(b).digest('hex');
const baseline=JSON.parse(await readFile('reports/nano-baseline.json','utf8'));
// Authorized Nano additions; all other existing functionality/assets must retain
// their exact pre-Nano bytes. This baseline is never regenerated by a build.
const changed=new Set(['src/LibrarySidebar.jsx','src/pinHover.js','src/PinHelper.jsx','src/App.jsx','src/styles.css','src/sketchBuilds.js','src/compiler-engine.js','src/workspaceSupport.js','src/compiler.js','src/WorkbenchDialogs.jsx','src/compiler.worker.js','src/WorkspacePanels.jsx','src/autocomplete.js','src/site/PublicPages.jsx','src/site/HelpPages.jsx','src/site/routes.js']);
// The later SEO wrapper appends static reading content. Its current revision
// has a separate, stricter unchanged-compiler/uploader gate below.
changed.add('src/site/SiteApp.jsx');
for(const [file,hash]of Object.entries(baseline))if(!changed.has(file))assert.equal(sha(await readFile(file)),hash,'Unexpected change to protected pre-Nano file: '+file);
await import('./check-seo-release.mjs');
const manifest=JSON.parse(await readFile('dist/avr/curated/manifest.json','utf8'));
const evidence=JSON.parse(await readFile('reports/nano-compatibility.json','utf8'));
assert.equal(evidence.buildId,manifest.buildId);assert.equal(evidence.boards.length,2);
for(const board of BOARD_PROFILES.slice(1)){
 const tests=evidence.boards.find(b=>b.id===board.id);assert.equal(tests.libraries.length,17);assert.equal(tests.baudRate,board.baudRate);assert.equal(tests.flashLimit,board.flashLimit);
 for(const test of tests.libraries){assert.equal(test.status,'PASS',test.name);assert.ok(test.hexSha256&&test.flashBytes>0&&test.flashBytes<=board.flashLimit&&test.ramBytes<=2048);const lib=manifest.libraries.find(l=>l.id===test.id);assert.equal(test.hash,lib.hash);assert.equal(lib.boardTests[board.id].status,'PASS');}
 assert.ok(tests.sketches.length>=8&&tests.sketches.every(s=>s.status==='PASS'));
}
assert.ok(evidence.checks.every(c=>c.status==='PASS'));assert.equal(evidence.checks.filter(c=>c.name.includes('previous Uno HEX')).length,4);
const variant=JSON.parse(await readFile('dist/avr/'+manifest.variants.eightanaloginputs.file,'utf8'));
assert.equal(variant.headers['/arduino/variant/pins_arduino.h'],await readFile('vendor/arduino-core/variants/eightanaloginputs/pins_arduino.h','utf8'));
const protocol=await readFile('reports/nano-protocol-final.txt','utf8');assert.match(protocol,/pass 28/);assert.match(protocol,/fail 0/);
const report={testedAt:new Date().toISOString(),status:'PASS',buildId:manifest.buildId,protectedFiles:Object.keys(baseline).length-changed.size,profiles:BOARD_PROFILES.map(b=>({id:b.id,baudRate:b.baudRate,flashLimit:b.flashLimit})),checks:['All 34 Nano library tests compile/link to genuine Intel HEX','Uno Blink, Button, Servo and Ultrasonic firmware byte-identical','Original Uno uploader, WASM executables, core, library sources, IndexedDB and project storage unchanged','Actual upstream Nano eightanaloginputs variant bundled','28 board/profile/pin/protocol tests including both Nano baud rates, reset, readback, timeout retry, disconnection and monitor reopen'],physicalHardware:'Not tested: no physical Uno or Nano connected.'};
await writeFile('reports/nano-validation.json',JSON.stringify(report,null,2)+'\n');
console.log('PASS — Nano exact-build compilation proof, board profiles, unchanged Uno pipeline and software-protocol regression evidence');
